// One task is built at a time: if any issue is Building, start nothing.
// Otherwise pick Adam's oldest Approved issue.
const STATES = ['Ideas', 'Refining', 'Ready for approval', 'Approved', 'Building',
  'Waiting for you', 'Stuck', 'Your QA', 'Done'];
const has = (issue, name) => issue.labels.some(l => l.name === name);

const issues = $input.all().map(i => i.json).filter(i => i.number && !i.pull_request);
if (issues.some(i => has(i, 'Building'))) return [];

const next = issues
  .filter(i => i.user?.login === 'AdamHoppe98' && has(i, 'Approved'))
  .sort((a, b) => a.number - b.number)[0];
if (!next) return [];

return [{ json: {
  number: next.number,
  title: next.title,
  otherLabels: next.labels.map(l => l.name).filter(n => !STATES.includes(n)),
} }];
